                        text: qsTr("Images")
                        enabled: !root.runLocked
                        onClicked: {
                            if (!studyBridge.hasCalibration) {
                                showMessage(qsTr("Error!"),
                                            qsTr("Load Calibration First!"))
                            } else {
                                pickImages()
                            }
                        }
                    }
                    Button {
                        text: qsTr("Models")
                        enabled: !root.runLocked
                        onClicked: {
                            if (!studyBridge.hasCalibration) {
                                showMessage(qsTr("Error!"),
                                            qsTr("Load Calibration First!"))
