// Plan 007 U6 — fake study-bridge surface (see FakePoseBridge.qml header).

import QtQuick

import QtQml.Models

QtObject {
    id: root

    property ListModel frameListModel: ListModel {}
    property ListModel modelListModel: ListModel {}
    property int currentFrame: 0
    property int primaryModelIndex: -1
    property var selectedModels: []
    property int selectedModelCount: 0
    property bool hasDataset: false
    property bool hasCalibration: false
    property bool calibratedForBiplane: false
    property int frameCount: 0

    // Every setCurrentFrame/toggleModelSelected call, in order.
    property var setCurrentFrameLog: []
    property var toggleLog: []

    signal datasetChanged()
    signal selectionChanged()
    signal messageRequested(string title, string message)

    function setCurrentFrame(i) {
        setCurrentFrameLog.push(i)
        currentFrame = i
    }

    function toggleModelSelected(i) {
        toggleLog.push(i)
        const idx = selectedModels.indexOf(i)
        if (idx === -1) {
            selectedModels = selectedModels.concat([i])
        } else {
            const copy = selectedModels.slice()
            copy.splice(idx, 1)
            selectedModels = copy
        }
        selectedModelCount = selectedModels.length
        if (selectedModels.length > 0) {
            primaryModelIndex = selectedModels[0]
        } else {
            primaryModelIndex = -1
        }
        selectionChanged()
    }

    function loadCalibration(path) { hasCalibration = true }
    function loadImages(paths) { }
    function loadModels(paths) { }
    function clearDataset() { }
    function applyViewerPose(index, x, y, z, xa, ya, za) { }
}
// Plan 007 U6 — fake bridge surfaces for the Qt Quick Test harness.
// Pure QML doubles of the C++ bridges' property/signal surface (the
// exact subset the view components read). No VTK, no backend.

import QtQuick

import QtQml.Models

QtObject {
    id: root

    property ListModel tableModel: ListModel {}
    property int rowCount: tableModel.count
    property bool dirty: false
    property string validationMessage: ""

    // [frame, model, axis, parsedValue] per successful commit.
    property var commitLog: []
    property var copyCalls: 0
    property var saveCalls: 0
    property var loadCalls: 0

    signal poseTableChanged()

    function setPoseValue(frame, model, axis, text) {
        const trimmed = String(text).trim()
        const v = parseFloat(trimmed)
        if (isNaN(v) || trimmed === "") {
            validationMessage = "Invalid numeric value"
            return false
        }
        commitLog.push([frame, model, axis, v])
        const keys = ["x", "y", "z", "xa", "ya", "za"]
        const key = keys[axis] !== undefined ? keys[axis] : "x"
        for (let i = 0; i < tableModel.count; ++i) {
            if (tableModel.get(i).frameIndex === frame) {
                tableModel.setProperty(i, key, v)
                break
            }
        }
        validationMessage = ""
        dirty = true
        return true
    }

    function copyPrevious() { copyCalls = copyCalls + 1 }
    function copyNext() { copyCalls = copyCalls + 1 }
    function savePoseFile(path) { saveCalls = saveCalls + 1 }
    function loadPoseFile(path) { loadCalls = loadCalls + 1 }
    function saveKinematics(path) { saveCalls = saveCalls + 1 }
    function loadKinematics(path) { loadCalls = loadCalls + 1 }
}

